(()=>{'use strict';
const $=s=>document.querySelector(s),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
let latest=null,imageBlob=null,imageUrl=null,exporting=false,exportBackground='';
const exportBackgrounds=[['','기본'],['normal-full','일반'],['hard-full','어려움'],['hell-full','지옥'],['abyss-full','심연'],['deepsea-full','심해'],['tower','탑'],['wall','성벽']];
function syncBackgrounds(){const host=$('#vote-backgrounds');host.replaceChildren();for(const [id,label]of exportBackgrounds){const button=el('button',undefined,'vote-background-option');button.type='button';button.disabled=exporting;button.setAttribute('aria-pressed',String(exportBackground===id));button.setAttribute('aria-label',label+' 배경');if(id){const img=el('img');img.src='/assets/maps/'+id+'.webp';img.alt='';button.append(img);}else button.append(el('span','✦','vote-background-default'));button.append(el('b',label));button.onclick=()=>{exportBackground=id;exportVotes();};host.append(button);}}
let ko={},mine=null,busy=false,active=0,ranking=Array(7).fill(''),dragged=-1;
const units=CoopData.demonsIn('supreme'),name=slug=>{const d=CoopData.DEMON_BY_SLUG.get(slug);return ko[d?.name]||d?.name||slug;};
function portrait(slug){const img=el('img');img.src='/assets/units/'+CoopData.DEMON_BY_SLUG.get(slug).img+'.webp';img.alt=name(slug);img.draggable=false;return img;}
function closePicker(){if($('#vote-picker').open)$('#vote-picker').close();}
function clearDrag(){dragged=-1;for(const card of $('#vote-choices').children)card.className=card.className.replace(/ dragging| drag-over/g,'');}
function moveRank(from,to){if(busy||from===to||from<0||to<0||from>=ranking.length||to>=ranking.length||!ranking[from])return;const selected=ranking[active];const [slug]=ranking.splice(from,1);ranking.splice(to,0,slug);active=selected?ranking.indexOf(selected):to;sync();$('#vote-status').textContent=`${name(slug)}을(를) ${to+1}위로 이동했습니다. 투표 버튼을 눌러 저장해 주세요.`;}
function sync(){const host=$('#vote-choices');host.replaceChildren();ranking.forEach((slug,i)=>{const button=el('button',undefined,'vote-rank-slot'+(active===i?' active':''));button.type='button';button.disabled=busy;button.draggable=!!slug&&!busy;button.ondragstart=e=>{if(busy||!slug){e.preventDefault();return;}dragged=i;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',slug);button.className+=' dragging';};button.ondragover=e=>{if(busy||dragged<0||dragged===i)return;e.preventDefault();e.dataTransfer.dropEffect='move';if(!button.className.includes(' drag-over'))button.className+=' drag-over';};button.ondragleave=()=>{button.className=button.className.replace(' drag-over','');};button.ondrop=e=>{if(busy||dragged<0)return;e.preventDefault();const from=dragged;clearDrag();moveRank(from,i);};button.ondragend=clearDrag;button.setAttribute('aria-label',`${i+1}위 ${slug?name(slug)+' 변경':'초마신 선택'}`);button.setAttribute('aria-pressed',String(active===i));button.append(el('strong',`${i+1}위 · ${7-i}점`));button.append(slug?portrait(slug):el('span','＋','vote-rank-empty'));button.append(el('span',slug?name(slug):'초마신 선택'));button.onclick=()=>{active=i;sync();$('#vote-picker').showModal();};host.append(button);});
const candidates=$('#vote-candidates');candidates.replaceChildren();$('#vote-picker-title').textContent=`${active+1}위 초마신 선택`;
for(const d of [...units].sort((a,b)=>name(a.slug).localeCompare(name(b.slug),'ko'))){const chosen=ranking.indexOf(d.slug),button=el('button',undefined,'vote-candidate');button.type='button';button.disabled=busy||(chosen!==-1&&chosen!==active);button.setAttribute('aria-label',name(d.slug)+(chosen===-1?' 선택':` · ${chosen+1}위 선택됨`));button.append(portrait(d.slug),el('b',name(d.slug)),el('small',chosen===-1?'선택하기':`${chosen+1}위 선택됨`));button.onclick=()=>{ranking[active]=d.slug;closePicker();sync();$('#vote-choices').children[active]?.focus?.();};candidates.append(button);}
$('#vote-submit').disabled=busy||ranking.some(v=>!v)||new Set(ranking).size!==7;$('#vote-refresh').disabled=busy;$('#vote-submit').textContent=mine?'이 순위로 투표 수정하기':'이 순위로 투표하기';}
function render(data){latest=data;$('#vote-image').disabled=false;mine=data.mine;$('#vote-total').textContent=`총 ${data.total.toLocaleString('ko-KR')}표 · 투표를 수정하면 기존 표를 대체합니다.`;const board=$('#dealer-tier-board');board.replaceChildren();if(!data.total)board.append(el('p','아직 투표가 없습니다. 첫 투표를 남겨 주세요.'));for(const tier of [...(data.rows.some(r=>r.tier==='0')?['0']:[]),'S','A','B','C','D','미득표']){const group=data.rows.filter(r=>r.tier===tier),row=el('section',undefined,'dealer-tier-row'+(tier==='0'?' tier-zero':tier==='S'?' tier-s':tier==='A'?' tier-a':'')),label=el('div',tier==='0'?'0 Tear':tier,'dealer-tier-label'),cards=el('div',undefined,'dealer-tier-cards');label.style.setProperty('--tier-color',({'0':'#ffdc73',S:'#d86f86',A:'#e5a64f',B:'#6e9bd2',C:'#7eae87',D:'#a49baa'})[tier]||'#aaa');for(const r of group){const card=el('article',undefined,'dealer-tier-card');card.append(portrait(r.slug),el('b',name(r.slug)),el('small',r.score+'점 · '+r.votes+'표'));cards.append(card);}if(!group.length)cards.append(el('span','해당 캐릭터 없음','dealer-tier-empty'));row.append(label,cards);board.append(row);}}

async function load(write=false){if(busy)return;busy=true;sync();$('#vote-status').textContent=write?'투표를 저장하는 중…':'결과를 불러오는 중…';try{const response=await fetch('/api/tier-votes',write?{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({ranking})}:{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error||'투표 서버에 연결할 수 없습니다.');render(data);if(mine)ranking=Array.from(mine);$('#vote-status').textContent=write?'투표를 반영했습니다.':mine?'기존 투표를 불러왔습니다. 순서를 바꿔 수정할 수 있습니다.':'좋아하는 캐릭터 7종을 선택해 주세요.';if(write){closePicker();$('#vote-total').textContent+=' 투표를 반영했습니다.';}}catch(error){$('#vote-status').textContent=error.message;}finally{busy=false;sync();}}
$('#vote-picker-close').onclick=closePicker;$('#vote-picker').onclick=e=>{if(e.target===$('#vote-picker')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePicker();}};
$('#tier-ballot').onsubmit=e=>{e.preventDefault();if(!$('#vote-submit').disabled)load(true);};$('#vote-refresh').onclick=()=>load();

async function exportVotes(){if(!latest||exporting)return;exporting=true;syncBackgrounds();$('#vote-share').disabled=true;$('#vote-download').hidden=true;$('#vote-image-open').hidden=true;$('#vote-share-status').textContent='선택한 배경으로 이미지를 만드는 중…';const background=exportBackground;const button=$('#vote-image');button.disabled=true;$('#vote-image-status').textContent='이미지를 만드는 중…';const data=structuredClone(latest);try{await document.fonts?.ready;const tiers=[...(data.rows.some(r=>r.tier==='0')?['0']:[]),'S','A','B','C','D','미득표'],groups=tiers.map(t=>data.rows.filter(r=>r.tier===t)),heights=groups.map(g=>Math.max(100,Math.ceil(g.length/8)*126+20)),canvas=document.createElement('canvas');canvas.width=1200;canvas.height=244+heights.reduce((a,b)=>a+b,0);const ctx=canvas.getContext('2d');if(!ctx)throw Error('이미지를 만들 수 없습니다.');const box=(x,y,w,h,r,color)=>{ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();};ctx.fillStyle='#0b1422';ctx.fillRect(0,0,1200,canvas.height);if(background){const map=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('맵 배경을 불러오지 못했습니다. 다시 선택해 주세요.'));img.src='/assets/maps/'+background+'.webp';});const scale=Math.max(1200/map.width,canvas.height/map.height),w=map.width*scale,h=map.height*scale;ctx.drawImage(map,(1200-w)/2,(canvas.height-h)/2,w,h);ctx.fillStyle='#08122299';ctx.fillRect(0,0,1200,canvas.height);}box(28,26,5,100,2,'#7de0c8');ctx.fillStyle='#7de0c8';ctx.font='bold 12px sans-serif';ctx.fillText('STACK LAB / COMMUNITY PICKS',50,40);ctx.fillStyle='#f0f5ff';ctx.font='bold 34px sans-serif';ctx.fillText('초마신 투표 티어리스트',50,82);ctx.font='15px sans-serif';ctx.fillStyle='#a4b8d1';ctx.fillText('함께 고른 7개의 선택, 한눈에 보는 초마신 티어',50,113);box(920,38,252,64,14,'#192b3d');ctx.textAlign='center';ctx.fillStyle='#e3f4ee';ctx.font='bold 21px sans-serif';ctx.fillText('총 '+data.total.toLocaleString('ko-KR')+'표',1046,66,224);ctx.fillStyle='#9eb7cb';ctx.font='12px sans-serif';ctx.fillText(new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date())+' · 집계 기준',1046,87);ctx.textAlign='left';ctx.fillStyle='#91a9bf';ctx.font='12px sans-serif';ctx.fillText('0 Tear: 득표 상위 1/5 내 최대 격차(20% 이상)로 그룹 분리  /  S~D: 남은 최고점 기준',50,146);let y=174;for(let i=0;i<tiers.length;i++){const tier=tiers[i],height=heights[i];const color=({'0':'#ffdc73',S:'#e68ba3',A:'#e4b074',B:'#7ca7d6',C:'#8cb69a',D:'#a6a3bc'})[tier]||'#70869d';box(28,y,1144,height-8,16,tier==='0'?(background?'#3c3421c9':'#3c3421'):(background?'#1a293bc4':'#1a293b'));box(28,y,100,height-8,16,color);ctx.textAlign='center';ctx.fillStyle=tier==='0'?'#513807':'#fff';ctx.font='bold 22px sans-serif';ctx.fillText(tier==='0'?'0 Tear':tier,78,y+height/2-2);ctx.font='11px sans-serif';ctx.fillText(groups[i].length+'종',78,y+height/2+20);const images=await Promise.all(groups[i].map(r=>new Promise(resolve=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>resolve(null);img.src='/assets/units/'+CoopData.DEMON_BY_SLUG.get(r.slug).img+'.webp';})));groups[i].forEach((r,j)=>{const x=140+(j%8)*126,top=y+10+Math.floor(j/8)*126,img=images[j];box(x+4,top-2,118,118,11,tier==='0'?'#51452b':'#223449');if(['0','S','A'].includes(tier)){ctx.fillStyle=tier==='0'?'#fff0a8':tier==='S'?'#f1b7c8':'#dfbf96';ctx.font=(tier==='0'?'18':tier==='S'?'13':'10')+'px sans-serif';ctx.fillText('✦',x+108,top+17);if(tier==='0'){ctx.font='11px sans-serif';ctx.fillText('✧',x+19,top+48);}}if(img){const scale=Math.min(68/img.width,68/img.height);ctx.drawImage(img,x+(126-img.width*scale)/2,top,img.width*scale,img.height*scale);}ctx.fillStyle='#fff';ctx.font='14px sans-serif';ctx.fillText(name(r.slug),x+63,top+87,118);ctx.fillStyle='#b9c9dd';ctx.font='12px sans-serif';ctx.fillText(r.score+'점 · '+r.votes+'표',x+63,top+108,118);});if(!groups[i].length){ctx.fillStyle='#aabbd0';ctx.font='16px sans-serif';ctx.fillText('해당 캐릭터 없음',640,y+50);}y+=height;}ctx.textAlign='left';ctx.fillStyle='#8299b1';ctx.font='12px sans-serif';ctx.fillText('STACK LAB · 초마신 커뮤니티 선호도 투표',28,canvas.height-24);ctx.textAlign='right';ctx.fillStyle='#7de0c8';ctx.fillText('7 PICKS / 28 POINTS',1172,canvas.height-24);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG 생성 실패');if(imageUrl)URL.revokeObjectURL(imageUrl);imageBlob=blob;imageUrl=URL.createObjectURL(blob);$('#vote-preview').src=imageUrl;$('#vote-download').href=imageUrl;$('#vote-image-open').href=imageUrl;let share=false;try{share=!!navigator.canShare?.({files:[new File([blob],'community-tier-list.png',{type:'image/png'})]});}catch{}$('#vote-share').hidden=!share;$('#vote-share-status').textContent='이미지를 길게 눌러 사진에 저장하거나 아래 버튼을 이용하세요.';if(!$('#vote-export').open)$('#vote-export').showModal();$('#vote-image-status').textContent='이미지를 만들었습니다.';}catch(error){$('#vote-image-status').textContent='이미지 저장 실패: '+error.message;$('#vote-share-status').textContent=error.message;}finally{button.disabled=false;exporting=false;syncBackgrounds();$('#vote-share').disabled=false;$('#vote-download').hidden=!imageBlob;$('#vote-image-open').hidden=!imageBlob;}}
syncBackgrounds();$('#vote-image').onclick=exportVotes;$('#vote-export-close').onclick=()=>$('#vote-export').close();$('#vote-share').onclick=async()=>{if(!imageBlob)return;try{await navigator.share({files:[new File([imageBlob],'community-tier-list.png',{type:'image/png'})],title:'초마신 투표 티어리스트'});}catch(error){$('#vote-share-status').textContent=error.name==='AbortError'?'공유를 취소했습니다. 파일 저장이나 이미지 길게 누르기를 이용하세요.':'파일 저장이나 이미지 크게 열기를 이용하세요.';}};
fetch('/ko.json').then(r=>r.json()).then(d=>ko=d).catch(()=>{}).finally(()=>{sync();load();});
})();
